// Sakura Academy interactive application.
const KEY='sakura-academy-v1';
const ASSESSMENT_TYPES=['vocabulary','grammar','dialogue','listening','writing'];
const WORD_GUIDANCE={
'わたし':'Use as a neutral, polite “I” when introducing yourself or when the speaker is not clear from context. Japanese often omits it once the topic is understood.',
'がくせい':'Use for a student at a school or university. Attach の to name a school or field: がっこうの がくせい (a student at the school).',
'せんせい':'Use as a respectful title for a teacher, doctor, or other qualified professional, usually after the person’s name. Avoid using it as a generic first-person job label.',
'ともだち':'Use for a friend, often with と (ともだちと, with a friend) or の (my friend). It is a familiar relationship word, not a formal title.',
'にほん':'Use as the country name Japan. にほんに (in/to Japan) marks location or destination; にほんの + noun means Japanese/of Japan.',
'なまえ':'Use for someone’s name. なまえは…です asks or states a name; おなまえ is a more polite way to refer to another person’s name.',
'はじめまして':'Say when meeting someone for the first time, usually at the start of an introduction. It is a set greeting, not a general “nice to meet you” for every later meeting.',
'よろしくおねがいします':'Say at the end of an introduction or when asking for someone’s cooperation. It expresses a polite hope for a good relationship; English translations depend on context.',
'これ':'Use for “this” when the item is near the speaker. It stands alone; before a noun use この (このほん, this book).',
'それ':'Use for “that” near the listener or already mentioned. Before a noun, change to その (そのかばん, that bag).',
'あれ':'Use for “that over there,” away from both people. Before a noun, use あの (あのほん, that book over there).',
'ほん':'Use for a book or volume. To say “this book,” put この before it; ほんをよみます means “read a book.”',
'かばん':'Use for a bag you carry. Combine with これ/その for pointing, or に入れる to say putting something inside it.',
'えん':'The Japanese currency counter 円 follows the amount: 500円. In prices it is read えん; it does not take の between the number and counter.',
'いくら':'Use いくらですか to ask a price or fare. For a count of items, use いくつ (or the item’s counter), as in りんごをいくつください.',
'たかい':'Use for high prices or tall/high objects, depending on context. たかいです means expensive/high; たかくないです is the polite negative.',
'みます':'Use for watching or looking at something, such as a film or TV. The thing viewed takes を: えいがをみます.',
'のみます':'Use for drinking liquids and taking medicine. The drink usually takes を: みずをのみます.',
'たべます':'Use for eating food. Mark the food with を: パンをたべます; use で for where you eat.',
'いきます':'Use for going to a destination; mark the destination with に or へ: がっこうにいきます. The destination particle is not を.',
'あした':'Use for tomorrow, commonly before the action: あしたいきます. Time words like this usually need no particle.',
'きょう':'Use for today, before the sentence or action. It normally appears without a particle: きょうべんきょうします.',
'えいが':'Use for a movie/film. It commonly pairs with みます and takes を as the object: えいがをみます.',
'みず':'Use for water. It often pairs with のみます; add お to sound polite when offering or requesting water (おみず).',
'きのう':'Use for yesterday, usually without a particle before a past-tense action: きのういきました.',
'こうえん':'Use for a public park. に marks going to or being at a park; こうえんで marks an activity done there.',
'がっこう':'Use for school as an institution or place. に marks destination/arrival; で marks an activity happening at school.',
'いきました':'Polite past form of いきます (“went”). Use に or へ before it for the destination: こうえんにいきました.',
'ありました':'Polite past of あります, for a thing or event that existed/was present. Use が for what existed and に for its location.',
'いました':'Polite past of います, for a person or animal that was present. Use が for who was there and に for the location.',
'どこ':'Use to ask where a place or destination is. Add ですか for “where is it?” or にいきますか for “where are you going?”.',
'うち':'Use for one’s home/house, often the speaker’s own. うちに means at/to home; うちで marks an activity done at home.',
'あたたかい':'Use for pleasantly warm weather, objects, or feelings. It describes warmth; for hot weather or food use あつい.',
'さむい':'Use for cold weather or how a person feels in cold air. For a cold object or drink, use つめたい instead.',
'あつい':'Use for hot weather, hot food/drink, or a hot object. The same reading can mean “thick” in other contexts; context clarifies it.',
'すき':'In the basic pattern, say Xが好きです to say you like something; add とても for “really like.” は can mark the topic or contrast, as in すしは好きです.',
'きれい':'Use for clean or beautiful places/things. It is a な-adjective: きれいなまち before a noun, まちはきれいです at sentence end.',
'うみ':'Use for the sea/ocean. に marks going to or being at the sea; で marks an activity there, such as swimming.',
'やま':'Use for a mountain. Combine with に/へ for destination and で for an activity done on the mountain.',
'てんき':'Use for weather. いいてんき means good weather; ask about it with てんきはどうですか.',
'あけて':'て-form of あけます, used for opening doors, windows, or containers. Add ください for a polite request; the object takes を.',
'しめて':'て-form of しめます, used for closing a door, window, or container. Add ください for a polite request.',
'まって':'て-form of まちます (“wait”). ちょっとまってください is a common polite request to wait a moment.',
'ください':'Use after a noun to request an item (みずをください) or after a verb’s て-form to request an action (まってください).',
'まど':'Use for a window. Open/close it with をあける/をしめる. Say まどのそばに or まどの近くに for “by/near the window”; use まどで for an activity done there.',
'ドア':'Use for a door, often with あける/しめる. This is a loanword written in katakana.',
'あさ':'Use for morning or this morning. It usually needs no particle as a time phrase; あさごはん means breakfast.',
'いそがしい':'Use for a person or schedule being busy. It is an い-adjective: いそがしいです; use いそがしくないです for “not busy.”',
'あね':'Use when speaking about your own older sister. For another person’s older sister, the respectful term is おねえさん.',
'あに':'Use when speaking about your own older brother. For another person’s older brother, use the respectful おにいさん.',
'いもうと':'Use for your own younger sister. For someone else’s younger sister, the usual polite term is 妹さん (いもうとさん).',
'おとうと':'Use for your own younger brother. To refer politely to someone else’s younger brother, おとうとさん is possible.',
'よんでいます':'て-form + います describes an action in progress or a continuing state: “is reading.” The object being read takes を.',
'はたらいています':'て-form + います describes someone currently working or their ongoing job. に can mark the workplace; で marks where the work happens.',
'しゃしん':'Use for a photograph/photo. しゃしんをとります means take a photo; しゃしんをみます means look at photos.',
'かぞく':'Use 家族 for family, often your own family. When referring politely to someone else’s family, use ご家族 (ごかぞく), not お家族.',
'やさい':'Use for vegetables as food or a category. It often combines with をたべます; count specific items with counters, not this general noun.',
'にく':'Use for meat. Specify the type before it (ぶたにく pork, とりにく chicken); it commonly takes を with cooking/eating verbs.',
'おいしい':'Use to say food or drink tastes good. It is an い-adjective; do not add の between it and the noun (おいしいりょうり).',
'おもいます':'Polite form of おもう (“think”). A thought or opinion is commonly followed by と: おいしいとおもいます.',
'いいます':'Polite form of いう (“say”). Quote the words with と: 「こんにちは」といいます; a person can be marked with に.',
'たのしい':'Use for an enjoyable experience or activity. Describe an event with は/がたのしいです; it is not usually used to describe a person as “funny.”',
'しゅうまつ':'Use for the weekend. It commonly appears without a particle as a time phrase: しゅうまつに (on the weekend) is also natural.',
'りょうり':'Use for cooking or a prepared dish/cuisine. りょうりをします means cook; りょうりをたべます means eat a dish.',
'みた':'Plain past form of みる (“saw/watched”). Use in casual speech or before a noun/clause; polite past is みました.',
'きいた':'Plain past of きく, which means “heard/listened” or “asked” depending on context. 〜をきいた often means heard; person にきいた means asked someone.',
'ながい':'Use for physical length or duration (a long road, long time). It is an い-adjective; its opposite is みじかい.',
'みじかい':'Use for physical shortness or brief duration. It commonly describes hair, distance, or time; its opposite is ながい.',
'げき':'Use for a play or drama performed on stage. げきをみる means watch a play; it differs from a movie (えいが).',
'ぶたい':'Use for a stage or performance platform. にあがる means go up onto the stage; で marks an event happening on stage.',
'おもしろい':'Use for something interesting or entertaining. It describes a topic, book, or film; it is an い-adjective and can be positive or context-dependent.',
'でんしゃ':'Use for a train, especially an electric railway train. でんしゃで行く uses で to mark the means of transport.',
'バス':'Use for a bus. Say バスで行きます (“go by bus”); use に乗ります for getting on a bus.',
'はやい':'Use for fast speed or an early time. It has two common senses; context distinguishes “fast” from “early.”',
'おそい':'Use for slow speed or a late time. Context distinguishes “slow” from “late”; it is not the same as “quiet.”',
'より':'Use after the comparison baseline: AはBよりたかいです (“A is more expensive than B”). The compared item is marked with は or が.',
'ふゆ':'Use for winter, usually as a time/topic phrase. ふゆに marks “in winter”; seasonal nouns generally do not need an article.',
'やすみ':'Use for a day off, holiday, or break. やすみです means “is off/on break”; やすみをとる means take time off.',
'よてい':'Use for a plan or schedule. 〜のよてい means “plans for …”; 予定があります means having plans.',
'けいけん':'Use for experience or something experienced. けいけんがあります means “have experience”; けいけんする means experience something.',
'りょこう':'Use for a trip or travel. りょこうにいく means go on a trip; りょこうをする also means travel.',
'きょうと':'Use as the place name Kyoto. に marks going to/being in Kyoto; で marks an action done there.',
'すし':'Use for sushi. It is often a mass/category noun; すしをたべます means eat sushi.',
'たべた':'Plain past form of たべる (“ate”). Use in casual conversation or before a noun/clause; polite past is たべました.',
'いった':'Plain past form of いく (“went”). Use に/へ for the destination; polite past is いきました.',
'あります':'Use for existence of things, not people/animals, and for possession. A thing takes が and its location takes に; possession often uses Xがあります.',
'したい':'Attach to a verb stem to say “want to do”: りょこうしたいです. The desired activity is often marked with を or が; it describes the speaker’s wish.',
'あたま':'Use for a person’s head or mind. For pain, say あたまがいたいです (“my head hurts”), with が marking the part that hurts.',
'いたい':'Use for physical pain or soreness. Mark the painful body part with が: のどがいたいです; it is an い-adjective.',
'びょういん':'Use for a hospital or clinic. に marks going to/being at the hospital; で marks treatment or an action happening there.',
'くすり':'Use for medicine or medication. くすりをのみます (“take medicine”) is the usual verb even for pills; follow dosage instructions.',
'やすみます':'Polite form of やすむ (“rest/take a day off”). Use に for the time and から for a reason; it can mean sleep/rest or be absent.',
'ねつ':'Use for a fever/raised temperature. ねつがあります means “have a fever”; say ねつがたかい for a high fever.',
'からだ':'Use for the body or physical health. からだにいい means good for the body/health; it is broader than a specific body part.',
'だいじょうぶ':'Use to ask or say whether someone is okay, something is safe, or a situation is fine. だいじょうぶですか is a caring check-in; context determines the sense.'
};
function fresh(){return {reviews:{},learned:{},completed:{},activity:{},answers:[],assessments:{},rewarded:{},tabVisits:{},grammarParts:{},strictMode:true,xp:0,kana:{},kanji:{},handwriting:{},goal:15,fontSize:'standard'}}
let state=fresh();try{let s=JSON.parse(localStorage.getItem(KEY));if(s&&typeof s==='object'&&!Array.isArray(s)){state={...fresh(),...s};for(let k of ['reviews','learned','completed','activity','kana','kanji','handwriting','assessments','rewarded','tabVisits','grammarParts'])if(!state[k]||typeof state[k]!=='object'||Array.isArray(state[k]))state[k]={};state.grammarParts=sanitizeGrammarParts(state.grammarParts,LESSONS);if(!Array.isArray(state.answers))state.answers=[];if(typeof state.strictMode!=='boolean')state.strictMode=true;if(!Number.isFinite(state.xp))state.xp=0;sanitizeStoredProgressSettings(state);sanitizeStrictProgressData(state);sanitizePracticeProgressData(state)}}catch(e){console.warn('Stored progress was invalid; starting safely.',e)}
let view='dashboard',lessonId=1,tab='vocab',romaji=false,filter='all',search='',builder=[],builderChecked=false,quiz=null,quizAnswered=false,quizLesson=0,showQuizText=false,flashIndex=0,flashBack=false,kanaScript='Hiragana',kanaExtra='basic',kanaQuiz=null,challengeEnd=0,challengeScore=0,kanjiIndex=0,feedback='',grammarFeedback='',strictNotice='',speechStatus='',practiceScript='Hiragana',practiceIndex=0,practiceUndo=[],audioPlayer=null,speechToastTimer=0,audioLessonId=1,audioLessonQueue=[],audioLessonIndex=0,audioLessonPaused=false,audioLessonComplete=false;
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){alert('Browser storage is unavailable or full. Export a backup to preserve progress.')}}
function markLessonTabVisited(id,key){if(!Array.isArray(state.tabVisits[id]))state.tabVisits[id]=[];if(!state.tabVisits[id].includes(key)){state.tabVisits[id].push(key);save()}}
function selectLessonTab(key){tab=key;feedback='';markLessonTabVisited(lessonId,key);render()}
function activity(){let d=today();state.activity[d]=(state.activity[d]||0)+1;save()}
function reward(x){state.xp+=x;activity();save()}function rewardOnce(key,points){return claimRewardOnce(state,key,points,reward)}
function speechToast(message){speechStatus=message;document.getElementById('speechToast')?.remove();let toast=document.createElement('div');toast.id='speechToast';toast.className='speech-toast';toast.setAttribute('role','status');toast.textContent=message;document.body.append(toast);clearTimeout(speechToastTimer);speechToastTimer=setTimeout(()=>{toast.remove();if(speechStatus===message)speechStatus=''},7000)}
function speak(t){let key=String(t).normalize('NFC').replace(/\s+/g,''),source=globalThis.SAKURA_AUDIO?.[key];if(source){try{if(window.speechSynthesis)window.speechSynthesis.cancel();audioPlayer=audioPlayer||new Audio();audioPlayer.pause();audioPlayer.onerror=()=>speechToast('Japanese audio could not play. Check media volume or try another browser.');audioPlayer.src=typeof source==='string'?source:source.src;audioPlayer.currentTime=0;speechStatus='';document.getElementById('speechToast')?.remove();let playing=audioPlayer.play();if(playing&&typeof playing.catch==='function')playing.catch(()=>speechToast('Japanese audio could not play in this browser.'));return}catch(e){speechToast('Japanese audio could not play in this browser.');return}}if(!('speechSynthesis'in window)||!window.speechSynthesis){speechToast('No saved audio or speech engine is available for this item in this browser.');return}try{window.speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(t);u.lang='ja-JP';u.rate=.82;let voices=window.speechSynthesis.getVoices(),v=voices.find(v=>v.lang.toLowerCase().startsWith('ja'));if(v)u.voice=v;u.onerror=()=>speechToast('Japanese speech is unavailable. Try a saved lesson audio example.');window.speechSynthesis.speak(u)}catch(e){speechToast('Japanese speech is unavailable. Try a saved lesson audio example.')}}
function updateAudioLessonStatus(){let status=$('audioLessonStatus'),current=$('audioLessonCurrent'),progress=$('audioLessonProgress'),bar=progress?.parentElement,control=$('audioLessonToggle'),scene=$('audioConversationScene');if(!status)return;let length=audioLessonQueue.length,entry=audioLessonQueue[audioLessonIndex],speaker=lessonAudioSpeaker(entry);if(control)control.textContent=audioLessonComplete?'▶ Play again':audioLessonPaused?'▶ Resume':length?'Ⅱ Pause':'▶ Play full lesson';scene?.classList.toggle('is-paused',audioLessonPaused);for(let role of ['A','B']){let person=$('audioSpeaker'+role),bubble=$('audioBubble'+role),active=speaker===role&&!audioLessonComplete;person?.classList.toggle('is-speaking',active);person?.setAttribute('aria-label',`Speaker ${role}${active?', speaking':', listening'}`);if(active&&entry&&bubble)bubble.textContent=entry.jp}let turn=$('audioConversationTurn');if(turn)turn.textContent=audioLessonComplete?'Conversation complete':speaker?`${audioLessonPaused?'Paused · ':'Now speaking · '}Speaker ${speaker}`:'Two speakers take turns in the lesson conversation';if(audioLessonComplete){status.textContent=`Lesson ${audioLessonId} complete · ${length} clips`;current.innerHTML='<b>おつかれさまでした。</b><br>Lesson audio complete.';if(progress)progress.style.width='100%';bar?.setAttribute('aria-valuenow',String(length));return}if(!length){let lesson=LESSONS[audioLessonId-1],count=buildLessonAudioQueue(lesson).length;status.textContent=`Ready · ${count} audio clips`;current.innerHTML=`<b>${esc(lesson.jp)}</b><br>${esc(lesson.en)}`;if(progress)progress.style.width='0%';bar?.setAttribute('aria-valuemax',String(count));bar?.setAttribute('aria-valuenow','0');return}let item=entry||audioLessonQueue[length-1],position=Math.min(audioLessonIndex+1,length),activeSpeaker=lessonAudioSpeaker(item);status.textContent=`${audioLessonPaused?'Paused':'Playing'} · ${position} of ${length}`;current.innerHTML=activeSpeaker?`<small>Conversation · Speaker ${activeSpeaker}</small><div class="muted">${esc(item.en)}</div>`:`<small>${esc(item.section)}</small><div class="audio-current-jp">${esc(item.jp)}</div><div class="muted">${esc(item.en)}</div>`;if(progress)progress.style.width=`${Math.round(100*position/length)}%`;bar?.setAttribute('aria-valuenow',String(position))}
function playAudioLessonStep(){if(!audioLessonQueue.length||audioLessonPaused)return;let item=audioLessonQueue[audioLessonIndex];if(!item){audioLessonComplete=true;audioLessonPaused=false;updateAudioLessonStatus();return}let key=item.jp.normalize('NFC').replace(/\s+/g,''),source=globalThis.SAKURA_AUDIO?.[key];updateAudioLessonStatus();if(source){try{window.speechSynthesis?.cancel();audioPlayer=audioPlayer||new Audio();audioPlayer.pause();audioPlayer.onended=()=>{audioLessonIndex++;playAudioLessonStep()};audioPlayer.onerror=()=>{audioLessonPaused=true;speechToast('Lesson audio could not play. Check media volume or try another browser.');updateAudioLessonStatus()};audioPlayer.src=typeof source==='string'?source:source.src;audioPlayer.currentTime=0;let playing=audioPlayer.play();if(playing&&typeof playing.catch==='function')playing.catch(()=>{audioLessonPaused=true;speechToast('Lesson audio could not play in this browser.');updateAudioLessonStatus()});return}catch(e){audioLessonPaused=true;speechToast('Lesson audio could not play in this browser.');updateAudioLessonStatus();return}}if(!('speechSynthesis'in window)||!window.speechSynthesis){audioLessonPaused=true;speechToast('Saved audio is missing for one lesson item, and speech playback is unavailable.');updateAudioLessonStatus();return}try{let utterance=new SpeechSynthesisUtterance(item.jp);utterance.lang='ja-JP';utterance.rate=.82;utterance.onend=()=>{audioLessonIndex++;playAudioLessonStep()};utterance.onerror=()=>{audioLessonPaused=true;speechToast('Lesson audio could not play in this browser.');updateAudioLessonStatus()};window.speechSynthesis.speak(utterance)}catch(e){audioLessonPaused=true;speechToast('Lesson audio could not play in this browser.');updateAudioLessonStatus()}}
function startAudioLesson(id=audioLessonId){audioLessonId=Math.max(1,Math.min(LESSONS.length,Number(id)||1));audioLessonQueue=buildLessonAudioQueue(LESSONS[audioLessonId-1]);audioLessonIndex=0;audioLessonPaused=false;audioLessonComplete=false;window.speechSynthesis?.cancel();audioPlayer=audioPlayer||new Audio();audioPlayer.onended=null;audioPlayer.onerror=null;audioPlayer.pause();render();playAudioLessonStep()}
function toggleAudioLesson(){if(!audioLessonQueue.length||audioLessonComplete){startAudioLesson(audioLessonId);return}if(audioLessonPaused){audioLessonPaused=false;if(window.speechSynthesis?.paused)window.speechSynthesis.resume();else if(audioPlayer&&!audioPlayer.ended&&audioPlayer.src){let result=audioPlayer.play();if(result&&typeof result.catch==='function')result.catch(()=>speechToast('Lesson audio could not resume in this browser.'))}else playAudioLessonStep();updateAudioLessonStatus();return}audioLessonPaused=true;audioPlayer?.pause();window.speechSynthesis?.pause();updateAudioLessonStatus()}
function restartAudioLesson(){startAudioLesson(audioLessonId)}
function selectAudioLesson(id){audioLessonQueue=[];audioLessonIndex=0;audioLessonPaused=false;audioLessonComplete=false;if(audioPlayer){audioPlayer.onended=null;audioPlayer.onerror=null;audioPlayer.pause()}window.speechSynthesis?.cancel();audioLessonId=Math.max(1,Math.min(LESSONS.length,Number(id)||1));render()}
function nav(v){if(view==='audio'&&v!=='audio'){audioLessonQueue=[];audioLessonIndex=0;audioLessonPaused=false;audioLessonComplete=false;if(audioPlayer){audioPlayer.onended=null;audioPlayer.onerror=null;audioPlayer.pause()}window.speechSynthesis?.cancel()}stopStrokeGuide();view=v;feedback='';builderChecked=false;strictNotice='';render();window.scrollTo(0,0)}
function goLesson(i,t='vocab'){i=Math.max(1,Math.min(LESSONS.length,Number(i)||1));if(state.strictMode&&i>strictUnlockedLesson()&&!strictLessonComplete(i)){strictNotice=`Finish Lesson ${strictUnlockedLesson()}'s checklist before opening later lessons.`;view='lessons';render();window.scrollTo(0,0);return}strictNotice='';if(state.strictMode&&i>lessonId&&i<=strictUnlockedLesson()&&strictLessonComplete(lessonId)&&state.completed[lessonId]!==true)recordLessonComplete(lessonId);lessonId=i;grammarFeedback='';tab=t;markLessonTabVisited(i,t);filter='all';search='';builder=[];builderChecked=false;feedback='';nav('lesson')}
function header(title,subtitle,eyebrow='YOUR LEARNING SPACE'){return `<div class="eyebrow">${eyebrow}</div><h1 class="title">${title}</h1><p class="subtitle">${subtitle}</p>`}
function percent(a,b){return b?Math.round(100*a/b):0}
function due(r){return !r||!r.due||r.due<=today()}
function streak(){let d=new Date(),n=0;for(let i=0;i<365;i++){let s=d.toLocaleDateString('en-CA');if(state.activity[s])n++;else if(i===0){d.setDate(d.getDate()-1);continue}else break;d.setDate(d.getDate()-1)}return n}
function strictChecklist(id){let l=LESSONS[id-1];if(!l)return[];let learned=l.vocab.filter(w=>state.learned[w.id]===true).length;return[
 {label:`Vocabulary marked learned (${learned}/${l.vocab.length})`,done:strictMilestoneDone(state,l,'vocabulary'),tab:strictChecklistTab('vocabulary')},
 {label:'Grammar sentence built correctly',done:strictMilestoneDone(state,l,'grammar'),tab:strictChecklistTab('grammar')},
 {label:'Conversation response correct',done:strictMilestoneDone(state,l,'conversation'),tab:strictChecklistTab('conversation')},
 {label:'Listening answer correct',done:strictMilestoneDone(state,l,'listening'),tab:strictChecklistTab('listening')},
 {label:'Writing answer typed correctly',done:strictMilestoneDone(state,l,'writing'),tab:strictChecklistTab('writing')},
 {label:'Assessment passed (4/5)',done:strictMilestoneDone(state,l,'assessment',ASSESSMENT_TYPES),tab:strictChecklistTab('assessment')}
]}
function strictLessonComplete(id){return strictChecklist(id).every(x=>x.done)}
function strictUnlockedLesson(){for(let i=1;i<=LESSONS.length;i++)if(!strictLessonComplete(i))return i;return LESSONS.length+1}
function strictCanNext(id){return id<LESSONS.length&&(!state.strictMode||(strictLessonComplete(id)&&id+1<=strictUnlockedLesson()))}
function setStrictMode(enabled){let next=!!enabled;if(next!==state.strictMode){quiz=null;quizAnswered=false;quizLesson=0}state.strictMode=next;strictNotice='';save();render()}
function recordLessonComplete(id){if(state.completed[id]!==true){state.completed[id]=true;reward(30)}}
function openChecklistStep(tab){selectLessonTab(tab);requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'smooth'}))}
function strictChecklistPanel(id){let checks=strictChecklist(id),done=checks.filter(x=>x.done).length,available=checklistStepAvailability(checks);return `<div class="card strict-checklist"><div class="row between"><h2>Lesson checklist</h2><span class="pill">${done}/${checks.length} complete</span></div><ul>${checks.map((x,i)=>`<li class="${x.done?'done':''}"><button class="checklist-step" onclick="openChecklistStep('${x.tab}')" ${available[i]?'':'disabled'} aria-label="${esc(x.label)}${x.done?' · review':' · open next activity'}"><span aria-hidden="true">${x.done?'✓':'○'}</span><span>${esc(x.label)}</span><span class="checklist-action" aria-hidden="true">${x.done?'Review':'Open'} →</span></button></li>`).join('')}</ul><p class="notice">Freehand writing stays optional because the canvas is not automatically graded.</p></div>`}
function dashboard(){
 let total=LESSONS.reduce((s,l)=>s+l.vocab.length,0),learned=Object.keys(state.learned).filter(k=>state.learned[k]===true).length,completed=Object.values(state.completed).filter(value=>value===true).length,acc=percent(state.answers.filter(x=>x.correct===true).length,state.answers.length),dueCount=allCards().filter(c=>due(state.reviews[c.id])).length,nextLesson=state.strictMode?Math.min(LESSONS.length,strictUnlockedLesson()):Math.min(12,completed+1);
 let days=Array.from({length:14},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(13-i));return {d:d.toLocaleDateString('en-CA'),n:state.activity[d.toLocaleDateString('en-CA')]||0}}),max=Math.max(1,...days.map(x=>x.n)),readiness=Math.round((completed/12*.45+learned/total*.25+countKnownFlags(state.kana,KANA.map(x=>x.ch))/KANA.length*.15+countKnownFlags(state.kanji,KANJI.map(x=>x.id))/KANJI.length*.15)*100);
 return `<div class="hero"><svg class="lesson-svg" viewBox="0 0 270 220" aria-hidden="true"><circle cx="175" cy="90" r="67" fill="#f4c7d2"/><path d="M45 175 Q130 85 240 175" fill="none" stroke="#333d6b" stroke-width="9" stroke-linecap="round"/><path d="M120 170 V65 M120 100 L80 70 M120 85 L155 45" stroke="#775f70" stroke-width="7" fill="none"/><g fill="#e89cb3"><circle cx="80" cy="70" r="18"/><circle cx="155" cy="45" r="19"/><circle cx="120" cy="65" r="16"/><circle cx="60" cy="110" r="10"/></g></svg>${header('Welcome back.','Continue your next lesson or browse the 12-part course.','SAKURA • BEGINNER ACADEMY')}<div class="row dashboard-actions"><button class="btn" onclick="goLesson(${nextLesson})">Continue learning →</button><button class="btn secondary" onclick="nav('lessons')">Browse lessons</button></div><label class="strict-toggle"><input type="checkbox" ${state.strictMode?'checked':''} onchange="setStrictMode(this.checked)"><span><b>Strict mode</b><small>Finish every lesson activity before advancing.</small></span></label></div><div class="grid dashboard-stats">${[['Lessons complete',completed+'/12'],['Words learned',learned+'/'+total],['Quiz accuracy',acc+'%'],['Reviews due',dueCount]].map(x=>`<div class="card"><div class="muted">${x[0]}</div><div class="stat">${x[1]}</div></div>`).join('')}</div><details class="card dashboard-activity"><summary><span>Study activity · ${streak()}-day streak</span><span class="pill">${state.xp} XP</span></summary><div class="row between"><span>Last 14 days · recorded learning actions</span><span class="pill">Daily goal ${state.goal} actions</span></div><div class="chart" aria-label="Daily activity chart">${days.map(x=>`<div title="${x.d}: ${x.n} actions" style="height:${Math.max(3,100*x.n/max)}%"></div>`).join('')}</div><p class="notice">Readiness estimate: ${readiness}% curriculum coverage, not a JLPT score or proficiency certification.</p></details>`
}
function lessonCards(){let unlocked=strictUnlockedLesson();return `<div class="grid">${LESSONS.map(l=>{let complete=state.strictMode?strictLessonComplete(l.id):state.completed[l.id]===true,locked=state.strictMode&&l.id>unlocked&&!complete,progress=complete?100:percent(l.vocab.filter(w=>state.learned[w.id]===true).length,l.vocab.length);return `<div class="card lesson-card"><div class="row between"><span class="lessonnum">LESSON ${String(l.id).padStart(2,'0')}</span>${complete?'✓ Completed':''}</div><h3>${esc(l.title)}</h3><div class="muted">${esc(l.description)}</div><div class="jp">${esc(l.jp)}</div><div class="progress"><div style="width:${progress}%"></div></div>${locked?`<p class="notice">Complete Lesson ${unlocked}'s checklist first.</p>`:''}<p><button class="btn small" ${locked?'disabled':''} onclick="goLesson(${l.id})">${locked?'🔒 Locked':'Open lesson →'}</button></p></div>`}).join('')}</div>`}
function lesson(){let l=LESSONS[lessonId-1];markLessonTabVisited(lessonId,tab);let tabs=[['vocab','Vocabulary'],['grammar','Grammar lab'],['dialogue','Conversation'],['builder','Sentence builder'],['listening','Listening'],['writing','Writing'],['quiz','Assessment']],canNext=strictCanNext(lessonId),canComplete=!state.strictMode||strictLessonComplete(lessonId);return `<div class="row between"><button class="btn ghost small" onclick="nav('lessons')">← All lessons</button><span class="pill">LESSON ${l.id} / 12</span></div>${header(esc(l.title),esc(l.description),'INTERACTIVE LESSON')}<div class="card"><div class="bigjp jp">${esc(l.jp)}</div><div>${esc(l.en)}</div><div class="row" style="margin-top:12px"><button class="btn secondary small" onclick="speak(LESSONS[lessonId-1].jp)">▶ Listen</button><button class="btn ghost small" onclick="romaji=!romaji;render()">${romaji?'Hide':'Show'} romaji</button></div></div><div class="tabs">${tabs.map(t=>{let status=lessonTabStatus(t[0],l,state,ASSESSMENT_TYPES),meta={'not-started':['Not started',''],'in-progress':['In progress','•'],complete:['Complete','✓'],'needs-review':['Needs review','!']}[status];return `<button class="tab status-${status} ${tab===t[0]?'active':''}" title="${meta[0]}" aria-label="${esc(t[1])}: ${meta[0]}" onclick="selectLessonTab('${t[0]}')">${t[1]}${meta[1]?`<span class="tab-status-mark" aria-hidden="true">${meta[1]}</span>`:''}</button>`}).join('')}</div>${({vocab:vocabulary,grammar:grammar,dialogue:dialogue,builder:sentenceBuilder,listening:listening,writing:writing,quiz:assessment})[tab](l)}${state.strictMode?strictChecklistPanel(lessonId):''}<div class="divider"></div><div class="row between"><button class="btn secondary" onclick="goLesson(${Math.max(1,lessonId-1)})" ${lessonId===1?'disabled':''}>← Previous</button><button class="btn" onclick="completeLesson()" ${canComplete?'':'disabled'}>${state.completed[lessonId]===true?'✓ Lesson completed':'Mark lesson complete'}</button><button class="btn secondary" onclick="goLesson(${Math.min(12,lessonId+1)})" ${canNext?'':'disabled'}>Next →</button></div>${state.strictMode&&!canNext&&lessonId<12?`<p class="notice">Complete every item in the checklist to unlock Next.</p>`:''}`}

function completeLesson(){if(state.strictMode&&!strictLessonComplete(lessonId)){feedback='Complete every strict mode checklist item before marking this lesson complete.';render();return}recordLessonComplete(lessonId);render()}
function vocabulary(l){let cats=[...new Set(l.vocab.map(w=>w.category))],list=l.vocab.filter(w=>(filter==='all'||w.category===filter)&&(w.jp.includes(search)||w.en.toLowerCase().includes(search.toLowerCase())));return `<div class="row between"><input class="field" aria-label="Search vocabulary" placeholder="Search words" value="${esc(search)}" oninput="search=this.value;updateWords()"><select class="field" aria-label="Vocabulary category" onchange="filter=this.value;updateWords()"><option value="all">All categories</option>${cats.map(c=>`<option ${filter===c?'selected':''}>${c}</option>`).join('')}</select></div><div id="wordList">${wordCards(list)}</div>`}
function updateWords(){let l=LESSONS[lessonId-1];$('wordList').innerHTML=wordCards(l.vocab.filter(w=>(filter==='all'||w.category===filter)&&(w.jp.includes(search)||w.en.toLowerCase().includes(search.toLowerCase()))))}
function wordCards(list){return `<div class="wordgrid" style="margin-top:16px">${list.map(w=>`<div class="word"><div class="row between"><span class="muted">${esc(w.category)}</span><button class="btn ghost small" aria-label="Hear ${esc(w.jp)}" onclick="speak('${w.jp}')">▶ Word</button></div><div class="jp">${esc(w.jp)}</div>${romaji?`<small>${esc(w.romaji)}</small>`:''}<p><b>${esc(w.en)}</b></p><div class="row between"><p class="notice jp">${esc(w.example)}</p><div class="row"><button class="btn ghost small" aria-label="Play example sentence" onclick="speak('${w.example}')">▶ Listen</button></div></div><p class="notice">${esc(w.exampleEn)}</p><details class="usage-note"><summary>How and when to use it</summary><p>${esc(WORD_GUIDANCE[w.jp]||'Use this word in the situations shown by the example. Notice its category and the particle or verb it appears with.')}</p></details><button class="btn small ${state.learned[w.id]===true?'secondary':''}" onclick="learn('${w.id}')">${state.learned[w.id]===true?'✓ Learned':'Mark learned'}</button></div>`).join('')}</div>`}
function learn(id){if(state.learned[id]!==true){state.learned[id]=true;rewardOnce('vocabulary:'+id,5)}else state.learned[id]=false;save();render()}
function grammar(l){let reviewed=new Set(Array.isArray(state.grammarParts[l.id])?state.grammarParts[l.id]:[]).size;return `<div class="card"><span class="eyebrow">PATTERN & MEANING</span><h2>${esc(l.rule)}</h2><p>${esc(l.explain)}</p><h3 class="section">Worked example</h3><p class="jp">${esc(l.jp)}</p><p>${esc(l.en)}</p><div class="row"><button class="btn ghost small" onclick="speak('${l.jp}')" aria-label="Play complete worked example">▶ Hear full sentence</button></div><p class="muted">Tap each word or particle to see its role and complete this section (${reviewed}/${l.builder.length} explored).</p><div class="grammar-parts">${l.builder.map((x,i)=>`<button id="grammar-part-${i}" class="token" onclick="inspect(${i})">${esc(x)}</button>`).join('')}</div><div id="inspect" class="feedback" aria-live="polite">${esc(grammarFeedback||'These tiles form the worked example above. Tap one to see its role.')}</div><p class="notice"><b>Common mistake:</b> ${esc(l.mistake)}</p><button class="btn" onclick="selectLessonTab('builder')">Practice sentence structure →</button></div>`}
function inspect(i){let l=LESSONS[lessonId-1],x=l.builder[i],w=l.vocab.find(w=>w.jp===x);if(!Number.isInteger(i)||i<0||i>=l.builder.length)return;if(!Array.isArray(state.grammarParts[l.id]))state.grammarParts[l.id]=[];if(!state.grammarParts[l.id].includes(i))state.grammarParts[l.id].push(i);let reviewed=new Set(state.grammarParts[l.id]).size;grammarFeedback=x+' · '+(w?w.en:({'は':'topic marker (pronounced wa)','を':'direct-object marker','に':'destination / time / location marker','が':'subject marker','です':'polite copula','より':'comparison baseline','ください':'polite request','と':'quotation marker'}[x]||'Grammatical unit. Observe its position in the complete sentence.'))+` · ${reviewed}/${l.builder.length} parts explored`;save();render();$(`grammar-part-${i}`)?.focus()}
function dialogue(l){let answered=feedback.startsWith('Correct')||feedback.startsWith('Not quite');return `<div class="card"><h2>In context: a short exchange</h2>${l.dialogue.filter(d=>d.who==='A').map(d=>`<div class="feedback"><b>Speaker A</b><div class="jp jp-dialogue">${esc(d.jp)}</div><div>${esc(d.en)}</div><div class="row"><button class="btn ghost small" onclick="speak('${d.jp}')">▶ Listen</button></div></div>`).join('')}<h3>What is a natural response?</h3><p>Choose a polite reply that fits what Speaker A said.</p>${(l.responseOptions||[]).map((x,i)=>`<button class="option" ${answered?'disabled':''} onclick="dialogueAnswer(${i})">${esc(x)}</button>`).join('')}${answered?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}" aria-live="polite">${esc(feedback)}</div><div class="feedback"><b>Speaker B</b><div class="jp jp-dialogue">${esc(l.dialogue.find(d=>d.who==='B')?.jp||'')}</div><div>${esc(l.dialogue.find(d=>d.who==='B')?.en||'')}</div><div class="row"><button class="btn ghost small" onclick="speak('${l.dialogue.find(d=>d.who==='B')?.jp||''}')">▶ Listen</button></div></div>${feedback.startsWith('Not quite')?`<button class="btn secondary" onclick="feedback='';render()">Try another response</button>`:''}`:''}<p class="notice">Listen for a reply that fits the situation and keeps the conversation natural and polite.</p></div>`}
function dialogueAnswer(i){if(feedback.startsWith('Correct')||feedback.startsWith('Not quite'))return;let l=LESSONS[lessonId-1],correct=i===l.responseAnswer;feedback=correct?'Correct! That reply fits the situation.':'Not quite. Compare the choices with the natural reply below.';state.answers.push({lesson:lessonId,format:'dialogue',correct,date:today()});if(correct)rewardOnce('lesson:'+lessonId+':dialogue',5);save();render()}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}let shuffled=[];
function sentenceBuilder(l){if(!shuffled.length||shuffled.join('')!==l.builder.slice().sort().join(''))shuffled=shuffle(l.builder);return `<div class="card"><h2>Build the sentence</h2><p>Translate: <b>${esc(l.builderEn)}</b></p><div class="row"><button class="btn ghost small" onclick="speak('${l.jp}')" aria-label="Hear the model sentence">▶ Hear model sentence</button></div><div class="answer" aria-label="Constructed sentence">${builder.map((w,i)=>`<button class="token" onclick="builder.splice(${i},1);builderChecked=false;render()">${esc(w)} ×</button>`).join('')}</div><div class="grammar-parts">${shuffled.map((w,i)=>`<button class="token" ${builder.filter(x=>x===w).length>=shuffled.filter(x=>x===w).length?'disabled':''} onclick="builder.push(shuffled[${i}]);builderChecked=false;render()">${esc(w)}</button>`).join('')}</div><button class="btn" ${builderChecked?'disabled':''} onclick="checkBuilder()">Check sentence</button> <button class="btn secondary" onclick="builder=[];builderChecked=false;render()">Reset</button>${feedback?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}">${esc(feedback)}</div>`:''}</div>`}
function checkBuilder(){if(builderChecked)return;builderChecked=true;let l=LESSONS[lessonId-1],ok=builder.join('|')===l.builder.join('|');feedback=ok?'Correct! '+l.builderEn:'Not quite. Check particle placement and word order. Model: '+l.builder.join(' ');state.answers.push({lesson:lessonId,format:'ordering',correct:ok,date:today()});if(ok)rewardOnce('lesson:'+lessonId+':ordering',10);save();render()}
function listening(l){let answered=feedback.startsWith('Correct.')||feedback.startsWith('Incorrect.');return `<div class="card"><h2>Listen and understand</h2><p>Press play, then choose the meaning. If speech is unsupported, reveal the Japanese transcript.</p><div class="row"><button class="btn" onclick="speak(LESSONS[lessonId-1].jp)">▶ Play Japanese</button><button class="btn secondary" onclick="$('transcript').classList.toggle('hidden')">Show / hide transcript</button></div><p id="transcript" class="jp jp-prompt hidden">${esc(l.jp)}</p>${shuffle([l.en,'I do not understand.','Please come here.']).map(x=>`<button class="option" ${answered?'disabled':''} onclick="listenAnswer(this.textContent)">${esc(x)}</button>`).join('')}${answered?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}" aria-live="polite">${esc(feedback)}</div><button class="btn secondary" onclick="feedback='';render()">Try another answer</button>`:''}</div>`}
function listenAnswer(x){if(feedback.startsWith('Correct.')||feedback.startsWith('Incorrect.'))return;let ok=x===LESSONS[lessonId-1].en;feedback=(ok?'Correct.':'Incorrect.')+' '+LESSONS[lessonId-1].jp+' = '+LESSONS[lessonId-1].en;state.answers.push({lesson:lessonId,format:'listening',correct:ok,date:today()});if(ok)rewardOnce('lesson:'+lessonId+':listening',8);save();render()}
function norm(s){return String(s).normalize('NFKC').toLowerCase().replace(/[\s\u3000。、！？!?.,'"「」]/g,'').replace(/ー/g,'ー')}
function writing(l){let w=l.vocab[0],answered=feedback.startsWith('Correct')||feedback.startsWith('Expected:');return `<div class="card"><h2>Typing and writing studio</h2><p>Type the Japanese for <b>${esc(w.en)}</b>. Hiragana or katakana as shown in the vocabulary list.</p><input id="writeInput" class="field" lang="ja" autocomplete="off" placeholder="Type Japanese here" ${answered?'disabled':''}><button class="btn" ${answered?'disabled':''} onclick="checkWriting()">Check</button>${feedback?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}" aria-live="polite">${esc(feedback)}</div>`:''}${answered?`<button class="btn secondary" onclick="feedback='';render()">Try again</button>`:''}<div class="divider"></div><h3>Character handwriting practice</h3><p class="muted">For a visual model, animated stroke order, and a dedicated canvas for hiragana, katakana, or beginner kanji, open guided character practice. Your typed answer above remains part of this lesson.</p><button class="btn secondary" onclick="nav('handwriting')">✎ Open character writing practice</button></div>`}
function checkWriting(){if(feedback.startsWith('Correct')||feedback.startsWith('Expected:'))return;let w=LESSONS[lessonId-1].vocab[0],v=$('writeInput').value,ok=norm(v)===norm(w.jp);feedback=ok?'Correct!':'Expected: '+w.jp+' ('+w.en+')';state.answers.push({lesson:lessonId,format:'typing',correct:ok,date:today()});if(ok)rewardOnce('lesson:'+lessonId+':writing',8);save();render()}


function practicePool(){return practiceScript==='Kanji'?KANJI.map(k=>({ch:k.ch,r:k.kun.split('・')[0],meaning:k.meaning,script:'Kanji',id:k.id})):KANA.filter(k=>k.script===practiceScript&&!k.extra).map((k,i)=>({ch:k.ch,r:k.r,meaning:k.r,script:practiceScript,id:practiceScript.slice(0,1)+i}))}
// Stroke paths from KanjiVG, © Ulrich Apel and contributors, CC BY-SA 3.0.
// Source: https://kanjivg.tagaini.net/ ; bundled paths are shared under CC BY-SA 3.0.

let strokeTimer=null,strokeStep=0;
function strokeOrderSvg(ch,upto=0){let a=STROKES[ch]||[];return `<svg viewBox="0 0 109 109" role="img" aria-label="Stroke order for ${ch}" style="width:min(100%,320px);height:auto;background:#fff;border:1px solid var(--line);border-radius:14px"><path d="M4 4h101v101H4zM4 54.5h101M54.5 4v101" fill="none" stroke="#eee8e7" stroke-width="0.8"/>${a.map((d,i)=>`<path d="${d}" fill="none" stroke="${i<upto?'#bd637c':'#c7c5cc'}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" opacity="${i<upto?'1':'.35'}"/>${i<upto?`<text x="${strokeLabel(i)[0]}" y="${strokeLabel(i)[1]}" font-size="9" font-weight="700" fill="#252e59">${i+1}</text>`:''}`).join('')}</svg>`}
function strokeLabel(i){return [[8,15],[90,17],[8,99],[92,99],[8,56],[96,56],[51,11],[51,103],[16,35],[95,35]][i%10]}
function showStrokeStep(n){let ch=practicePool()[practiceIndex%practicePool().length].ch;strokeStep=Math.max(0,Math.min(STROKES[ch].length,n));let v=$('strokeGuide');if(v)v.innerHTML=strokeOrderSvg(ch,strokeStep);let l=$('strokeStepLabel');if(l)l.textContent=strokeStep===0?'Ready · '+STROKES[ch].length+' strokes':`Stroke ${strokeStep} of ${STROKES[ch].length}`}
function stopStrokeGuide(){if(strokeTimer){clearInterval(strokeTimer);strokeTimer=null}let b=$('strokePlay');if(b)b.textContent='▶ Play order'}
function playStrokeOrder(){stopStrokeGuide();showStrokeStep(0);let ch=practicePool()[practiceIndex%practicePool().length].ch;let b=$('strokePlay');if(b)b.textContent='❚❚ Playing';strokeTimer=setInterval(()=>{if(strokeStep>=STROKES[ch].length){stopStrokeGuide();return}showStrokeStep(strokeStep+1)},850)}
function strokePrev(){stopStrokeGuide();showStrokeStep(strokeStep-1)}function strokeNext(){stopStrokeGuide();showStrokeStep(strokeStep+1)}
function handwriting(){let pool=practicePool(),item=pool[practiceIndex%pool.length],done=state.handwriting||{};return `${header('Handwriting practice','Learn each character in stages: hiragana, katakana, then 84 approximate N5 kanji. Draw with your finger, mouse, or stylus.','WRITE JAPANESE')}<div class="row"><button class="btn ${practiceScript==='Hiragana'?'':'secondary'}" onclick="setPracticeScript('Hiragana')">Hiragana</button><button class="btn ${practiceScript==='Katakana'?'':'secondary'}" onclick="setPracticeScript('Katakana')">Katakana</button><button class="btn ${practiceScript==='Kanji'?'':'secondary'}" onclick="setPracticeScript('Kanji')">Beginner kanji</button><span class="pill">${countKnownFlags(done,practicePool().map(x=>practiceScript+':'+x.id))} practiced</span></div><div class="card handwriting-card" style="margin-top:18px"><div class="row between"><div><div class="eyebrow">${practiceScript} · ${practiceIndex%pool.length+1} of ${pool.length}</div><div class="bigjp jp practice-model">${item.ch}</div><b>${esc(item.r)} · ${esc(item.meaning)}</b></div><div class="notice">Reference character<br><span class="jp practice-reference-char">${item.ch}</span></div></div><p class="notice practice-hint">Trace the model, then try writing it from memory. Freehand practice is not automatically graded.</p><div class="practice-workspace"><div class="card stroke-card" style="margin:16px 0"><div class="row between"><div><h3 style="margin:0">Correct stroke order</h3><p id="strokeStepLabel" class="notice">Ready · ${STROKES[item.ch].length} strokes</p></div><div class="row"><button id="strokePlay" class="btn" onclick="playStrokeOrder()">▶ Play order</button><button class="btn secondary" onclick="strokePrev()">← Step</button><button class="btn secondary" onclick="strokeNext()">Step →</button></div></div><div id="strokeGuide" style="text-align:center;margin:10px 0">${strokeOrderSvg(item.ch)}</div><p class="notice">Strokes appear one at a time in numbered order. Source: <a href="https://kanjivg.tagaini.net/" target="_blank" rel="noopener">KanjiVG</a>, © Ulrich Apel and contributors, CC BY-SA 3.0. Bundled diagrams are shared under CC BY-SA 3.0.</p></div><canvas id="practiceDraw" width=900 height=500 aria-label="Handwriting practice canvas" style="display:block;width:100%;height:clamp(300px,55vh,500px);border:1px solid #e9c4cf;border-radius:16px;background-color:#fff;background-image:linear-gradient(90deg,transparent 49.85%,#f3e8ec 50%,transparent 50.15%),linear-gradient(transparent 49.85%,#f3e8ec 50%,transparent 50.15%);touch-action:none;"></canvas></div><div class="row practice-actions" style="margin-top:14px"><button class="btn secondary" onclick="undoPractice()" ${practiceUndo.length?'':'disabled'}>Undo stroke</button><button class="btn ghost" onclick="clearPractice()">Clear</button><button class="btn secondary" onclick="speak('${item.ch}')">▶ Listen</button><span style="flex:1"></span><button class="btn secondary" onclick="stepPractice(-1)">← Previous</button><button class="btn" onclick="finishPractice('${practiceScript}:${item.id}')">Mark practiced · Next →</button></div><p class="notice">Progress saves on this device. ${practiceIndex+1>=pool.length?'You reached the end of this set; next wraps to the first character.':''}</p></div>`}
function setupPracticeCanvas(){let c=$('practiceDraw');if(!c)return;let ctx=c.getContext('2d'),drawing=false,points=[];ctx.strokeStyle='#252e59';ctx.lineWidth=9;ctx.lineCap='round';ctx.lineJoin='round';const pos=e=>{let r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}};c.onpointerdown=e=>{drawing=true;points=[];c.setPointerCapture(e.pointerId);let p=pos(e);points.push(p);ctx.beginPath();ctx.moveTo(p.x,p.y)};c.onpointermove=e=>{if(!drawing)return;let p=pos(e);points.push(p);ctx.lineTo(p.x,p.y);ctx.stroke()};c.onpointerup=c.onpointercancel=()=>{if(drawing&&points.length){practiceUndo.push(points);drawing=false}}}
function redrawPractice(){let c=$('practiceDraw');if(!c)return;let ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);for(let stroke of practiceUndo){ctx.beginPath();stroke.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke()}}
function undoPractice(){practiceUndo.pop();redrawPractice();render()}function clearPractice(){practiceUndo=[];redrawPractice();render()}function clearPracticeForNext(){practiceUndo=[]}
function setPracticeScript(script){stopStrokeGuide();practiceScript=script;practiceIndex=0;strokeStep=0;practiceUndo=[];render()}function stepPractice(n){stopStrokeGuide();strokeStep=0;practiceIndex=(practiceIndex+n+practicePool().length)%practicePool().length;practiceUndo=[];render()}function finishPractice(key){stopStrokeGuide();strokeStep=0;state.handwriting=state.handwriting||{};if(!state.handwriting[key]){state.handwriting[key]=true;rewardOnce('handwriting:'+key,2)}practiceIndex=(practiceIndex+1)%practicePool().length;practiceUndo=[];render()}
function newAssessment(l){let words=shuffle(assessmentWordPool(l,state.learned));if(words.length<2)return null;return {questionTypes:shuffle([...ASSESSMENT_TYPES]),wordIds:words.slice(0,2).map(w=>w.id),results:[],passed:false}}
function assessmentRun(l){let existing=state.assessments[l.id],run=ensureAssessmentRun(existing,l,ASSESSMENT_TYPES,newAssessment,state.learned);if(run!==existing){state.assessments[l.id]=run;save()}return run}
function makeQuiz(l){let run=assessmentRun(l),index=run.results.length,type=run.questionTypes[index],words=id=>l.vocab.find(w=>w.id===id)||l.vocab[0],chosen=(type==='writing'?words(run.wordIds[1]):words(run.wordIds[0])),otherLessons=LESSONS.filter(x=>x.id!==l.id),options=(correct,candidates)=>shuffle([correct,...shuffle([...new Set(candidates.filter(x=>x!==correct))]).slice(0,3)]);quiz={type,index,typed:false,options:[],jp:'',prompt:'',correct:'',explanation:''};if(type==='vocabulary'){quiz.jp=chosen.jp;quiz.prompt=`What does ${chosen.jp} mean?`;quiz.correct=chosen.en;quiz.options=options(quiz.correct,l.vocab.map(w=>w.en));quiz.explanation=`${chosen.jp} = ${chosen.en}.`}else if(type==='grammar'){quiz.prompt=`Which Japanese sentence means “${l.builderEn}”?`;quiz.correct=l.builder.join(' ');quiz.options=options(quiz.correct,otherLessons.map(x=>x.builder.join(' ')));quiz.explanation=`${quiz.correct} = ${l.builderEn}.`}else if(type==='dialogue'){let line=l.dialogue.find(d=>d.who==='A')||l.dialogue[0];quiz.jp=line.jp;quiz.prompt='What does Speaker A say?';quiz.correct=line.en;quiz.options=options(quiz.correct,otherLessons.map(x=>(x.dialogue.find(d=>d.who==='A')||x.dialogue[0]).en));quiz.explanation=`${line.jp} = ${line.en}.`}else if(type==='listening'){quiz.jp=l.jp;quiz.prompt='Listen to the Japanese, then choose its meaning.';quiz.correct=l.en;quiz.options=options(quiz.correct,otherLessons.map(x=>x.en));quiz.explanation=`${l.jp} = ${l.en}.`}else{quiz.prompt=`Type the Japanese for “${chosen.en}”.`;quiz.correct=chosen.jp;quiz.typed=true;quiz.jp=chosen.jp;quiz.explanation=`${chosen.jp} = ${chosen.en}.`}quizAnswered=false;quizLesson=l.id;showQuizText=false;feedback='';return quiz}
function retryAssessment(id){let l=LESSONS[id-1];if(!l)return;state.assessments[id]=newAssessment(l);quiz=null;quizAnswered=false;quizLesson=id;feedback='';save();makeQuiz(l);render()}
function assessment(l){let pool=assessmentWordPool(l,state.learned);if(pool.length<2)return `<div class="card"><div class="eyebrow">ASSESSMENT LOCKED</div><h2>Study the lesson vocabulary first</h2><p>Mark at least two words in this lesson as learned before starting the assessment. Vocabulary questions will use words you have studied.</p><button class="btn" onclick="selectLessonTab('vocab')">Review vocabulary →</button></div>`;let run=assessmentRun(l),score=run.results.filter(Boolean).length;if(run.passed)return `<div class="card"><div class="eyebrow">ASSESSMENT PASSED</div><h2>Lesson assessment complete</h2><div class="stat">${score} / 5</div><p>You passed with at least 4 correct answers across vocabulary, grammar, dialogue, listening, and writing.</p></div>`;if(run.results.length>=5)return `<div class="card"><div class="eyebrow">ASSESSMENT RESULT</div><h2>Try the assessment again</h2><div class="stat">${score} / 5</div><p>You need 4 correct answers to pass. Review the lesson and try a fresh set.</p><button class="btn" onclick="retryAssessment(${l.id})">Retry assessment</button></div>`;if(!quiz||quizLesson!==l.id||(quiz.index!==run.results.length&&!(quizAnswered&&quiz.index+1===run.results.length)))makeQuiz(l);let q=quiz,number=q.index+1,body=q.type==='listening'?`<div class="row"><button class="btn" onclick="speak('${q.jp}')">▶ Play Japanese</button><button class="btn secondary" onclick="showQuizText=!showQuizText;render()">${showQuizText?'Hide':'Show'} text</button></div>${showQuizText?`<p class="jp jp-dialogue">${esc(q.jp)}</p>`:''}${q.options.map(x=>`<button class="option" ${quizAnswered?'disabled':''} onclick="checkQuiz(this.textContent)">${esc(x)}</button>`).join('')}`:q.typed?`<p>${esc(q.prompt)}</p><input class="field" id="quizInput" lang="ja" autocomplete="off" ${quizAnswered?'disabled':''}><button class="btn" ${quizAnswered?'disabled':''} onclick="checkQuiz($('quizInput').value,true)">Check</button>`:`<p>${esc(q.prompt)}</p>${q.type==='dialogue'?`<p class="jp jp-prompt">${esc(q.jp)}</p>`:''}${q.options.map(x=>`<button class="option ${q.type==='grammar'?'jp':''}" ${quizAnswered?'disabled':''} onclick="checkQuiz(this.textContent)">${esc(x)}</button>`).join('')}`;return `<div class="card"><div class="row between"><h2>Lesson assessment</h2><span class="pill">Question ${number} of 5 · ${score} correct</span></div><p>Five questions cover vocabulary, grammar, dialogue, listening, and typed Japanese. You need at least four correct answers to pass.</p><span class="pill">${({vocabulary:'Vocabulary · Japanese → English',grammar:'Grammar · sentence meaning',dialogue:'Dialogue · comprehension',listening:'Listening · comprehension',writing:'Writing · type Japanese'})[q.type]}</span>${q.type==='listening'?`<p>${esc(q.prompt)}</p>`:''}${body}${feedback?`<div class="feedback ${feedback.startsWith('Correct')?'good':'bad'}" aria-live="polite">${esc(feedback)}</div>`:''}${run.results.length<5?`<button class="btn secondary" ${quizAnswered?'':'disabled'} onclick="makeQuiz(LESSONS[lessonId-1]);render()">Next question →</button>`:''}</div>`}
function checkQuiz(v,typed=false){if(quizAnswered||quizLesson!==lessonId||!quiz)return;let run=assessmentRun(LESSONS[lessonId-1]);if(quiz.index!==run.results.length)return;let ok=quiz.typed?typed&&norm(v)===norm(quiz.correct):!typed&&String(v)===quiz.correct;quizAnswered=true;feedback=(ok?'Correct! ':'Not quite. ')+quiz.explanation;state.answers.push({lesson:lessonId,format:'assessment-'+quiz.type,correct:ok,date:today()});run.results.push(ok);if(run.results.length===5)run.passed=run.results.filter(Boolean).length>=4;if(ok)reward(10);save();render()}
function allCards(){let lessonWords=LESSONS.flatMap(l=>l.vocab);let lessonIds=new Set(lessonWords.map(w=>w.jp+'|'+norm(w.en)));let n5=N5_VOCAB.filter(w=>!lessonIds.has(w.word+'|'+norm(w.meanings?.[0]||''))).map(w=>({id:'n5-'+w.id,jp:w.word,en:w.meanings.join('; '),category:'N5 vocabulary',romaji:w.romaji,example:w.examples?.[0]?.ja||w.word,exampleEn:w.examples?.[0]?.en||w.meanings[0]}));return lessonWords.concat(n5)}
function reviewCard(id,quality){let old=state.reviews[id]||{ease:2.5,interval:0,reps:0,history:[]};let r={...old};if(quality<3){r.reps=0;r.interval=1}else{r.interval=r.reps===0?1:r.reps===1?6:Math.max(1,Math.round(r.interval*r.ease));r.reps++}r.ease=Math.max(1.3,r.ease+(0.1-(5-quality)*(0.08+(5-quality)*0.02)));let d=new Date();d.setDate(d.getDate()+r.interval);r.due=d.toLocaleDateString('en-CA');r.history=[...(r.history||[]).slice(-99),{date:today(),quality}];state.reviews[id]=r;if(quality>=3){state.learned[id]=true;rewardOnce('review:'+id+':'+today(),5)}else activity();save();flashIndex++;flashBack=false;render()}
function flashcards(){let cards=allCards().filter(w=>due(state.reviews[w.id]));if(!cards.length)return `${header('Spaced repetition','No cards due. Return tomorrow or browse lessons.')}<button class="btn" onclick="nav('lessons')">Browse lessons</button>`;let w=cards[flashIndex%cards.length];return `${header('Daily review','SM-2-inspired scheduling: Again resets to 1 day; Good uses 1/6 days then ease-adjusted intervals. Ease has a 1.3 minimum.','SPACED REPETITION')}<p class="pill">${cards.length} cards due · Card ${flashIndex%cards.length+1}</p><div class="flash" role="button" tabindex="0" onclick="flashBack=!flashBack;render()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();flashBack=!flashBack;render()}"><div>${flashBack?`<div class="stat">${esc(w.en)}</div><div class="jp">${esc(w.jp)}</div>`:`<div class="jp">${esc(w.jp)}</div><small>Tap or press Enter to reveal meaning</small>`}</div></div><div class="row" style="justify-content:center"><button class="btn secondary" onclick="speak('${w.jp}')">▶ Hear</button>${flashBack?`<button class="btn" onclick="reviewCard('${w.id}',1)">Again</button><button class="btn" onclick="reviewCard('${w.id}',3)">Hard</button><button class="btn" onclick="reviewCard('${w.id}',4)">Good</button><button class="btn" onclick="reviewCard('${w.id}',5)">Easy</button>`:''}</div><p class="notice">Cards begin due immediately. Review history and intervals are stored only in this browser unless exported.</p>`}
function kanaPage(){let list=KANA.filter(x=>x.script===kanaScript&&(kanaExtra==='all'||(kanaExtra==='basic'?!x.extra:kanaExtra==='modified'?x.extra&&!x.combo:x.combo)));return `${header('Kana masterclass','Learn hiragana, katakana, voiced sounds and combinations. Tap any symbol to hear it.','JAPANESE WRITING')}<div class="row"><button class="btn ${kanaScript==='Hiragana'?'':'secondary'}" onclick="kanaScript='Hiragana';render()">Hiragana</button><button class="btn ${kanaScript==='Katakana'?'':'secondary'}" onclick="kanaScript='Katakana';render()">Katakana</button><select class="field" onchange="kanaExtra=this.value;render()"><option value="basic" ${kanaExtra==='basic'?'selected':''}>Basic</option><option value="modified" ${kanaExtra==='modified'?'selected':''}>Dakuten / handakuten</option><option value="combo" ${kanaExtra==='combo'?'selected':''}>Combination sounds</option><option value="all" ${kanaExtra==='all'?'selected':''}>All</option></select></div><div class="kana-grid" style="margin:20px 0">${list.map(x=>`<button class="kana" onclick="kanaPick('${x.ch}')"><strong>${x.ch}</strong>${romaji?`<small>${x.r}</small>`:''}${state.kana[x.ch]===true?' <small>✓</small>':''}</button>`).join('')}</div><div class="card"><h3>Recognition challenge</h3><button class="btn" onclick="newKanaQuiz()">${kanaQuiz?'New question':'Start quiz'}</button>${kanaQuiz?`<div class="bigjp jp">${kanaQuiz.ch}</div><p>Choose the reading</p>${kanaQuiz.options.map(x=>`<button class="btn secondary" style="margin:4px" onclick="kanaAnswer('${x}')">${x}</button>`).join('')}`:''}${feedback?`<div class="feedback">${esc(feedback)}</div>`:''}<p class="notice">Timed challenge: <button class="btn ghost small" onclick="startTimer()">Start 60 seconds</button> <span id="timerLabel">${challengeEnd?'Challenge active':'Not started'}</span> · Correct: ${challengeScore}</p></div>`}
function kanaPick(ch){let k=KANA.find(x=>x.ch===ch);if(!state.kana[ch]){state.kana[ch]=true;rewardOnce('kana:'+ch,2)}feedback=ch+' is read '+k.r+'. Practice its shape and sound.';speak(ch);render()}
function newKanaQuiz(){let pool=KANA.filter(x=>x.script===kanaScript&&!x.extra),k=pool[Math.floor(Math.random()*pool.length)];kanaQuiz={ch:k.ch,r:k.r,options:shuffle([k.r,...shuffle([...new Set(pool.map(x=>x.r).filter(r=>r!==k.r))]).slice(0,3)])};feedback='';render()}
function kanaAnswer(r){let ok=r===kanaQuiz.r;feedback=ok?'Correct! '+kanaQuiz.ch+' = '+r:'Incorrect. '+kanaQuiz.ch+' = '+kanaQuiz.r;if(ok){if(!state.kana[kanaQuiz.ch]){state.kana[kanaQuiz.ch]=true;rewardOnce('kana:'+kanaQuiz.ch,4)}if(challengeEnd&&Date.now()<challengeEnd)challengeScore++}else activity();save();if(challengeEnd&&Date.now()>challengeEnd){feedback+=' · Time is up! Score: '+challengeScore;challengeEnd=0}kanaQuiz=null;render()}
function startTimer(){challengeEnd=Date.now()+60000;challengeScore=0;newKanaQuiz();let interval=setInterval(()=>{let el=$('timerLabel');if(!el||!challengeEnd){clearInterval(interval);return}let n=Math.max(0,Math.ceil((challengeEnd-Date.now())/1000));el.textContent=n+' seconds left';if(!n){challengeEnd=0;clearInterval(interval);el.textContent='Time up · '+challengeScore+' correct'}},250)}
function kanjiPage(){let k=KANJI[kanjiIndex];return `${header('Kanji explorer','84 approximate N5 kanji with meanings, readings, examples, and stroke order.','FOUNDATIONS')}<div class="kana-grid">${KANJI.map((x,i)=>`<button class="kana" onclick="kanjiIndex=${i};render()"><strong>${x.ch}</strong><small>${state.kanji[x.id]===true?'✓ ':''}${esc(x.meaning.split(' / ')[0])}</small></button>`).join('')}</div><div class="card" style="margin-top:20px"><div class="bigjp jp">${k.ch}</div><h2>${esc(k.meaning)}</h2><p><b>On’yomi:</b> ${esc(k.on)}</p><p><b>Kun’yomi:</b> ${esc(k.kun)}</p><p><b>Example:</b> ${esc(k.example)}</p><button class="btn secondary" onclick="speak('${k.ch}')">▶ Listen</button> <button class="btn" onclick="if(!state.kanji['${k.id}']){state.kanji['${k.id}']=true;rewardOnce('kanji:${k.id}',5)}render()">${state.kanji[k.id]===true?'✓ Studied':'Mark studied'}</button></div><p class="notice">Readings are common beginner readings, not exhaustive. Some examples use a reading that applies to the whole compound.</p>`}
function applyTextSize(){document.body.dataset.textSize=state.fontSize||'standard'}
function audioDialogueScene(l){let line=role=>l.dialogue.find(x=>x.who===role)||{jp:'…',en:''};let person=role=>`<div class="audio-dialogue-person audio-dialogue-person-${role.toLowerCase()}" id="audioSpeaker${role}" aria-label="Speaker ${role}, listening"><div class="audio-dialogue-bubble" id="audioBubble${role}">${esc(line(role).jp)}</div><svg class="audio-stick-figure" viewBox="0 0 80 100" aria-hidden="true"><circle class="stick-head" cx="40" cy="17" r="13"/><circle class="stick-eye" cx="35.5" cy="15" r="1.2"/><circle class="stick-eye" cx="44.5" cy="15" r="1.2"/><path class="mouth-closed" d="M36 22 Q40 25 44 22"/><ellipse class="mouth-open" cx="40" cy="23" rx="2.5" ry="3.5"/><path class="stick-body" d="M40 31 L40 59 M40 38 L22 49 M40 38 L58 49 M40 59 L25 82 M40 59 L55 82"/></svg><span class="audio-dialogue-name">Speaker ${role}<span class="audio-voice-bars" aria-hidden="true"><i></i><i></i><i></i></span></span></div>`;return `<div class="audio-dialogue-scene" id="audioConversationScene" aria-label="Lesson conversation with two speakers">${person('A')}${person('B')}<p id="audioConversationTurn" class="audio-conversation-turn" aria-live="polite">Two speakers take turns in the lesson conversation</p></div>`}
function audioLessons(){let l=LESSONS[audioLessonId-1],queue=audioLessonQueue.length?audioLessonQueue:buildLessonAudioQueue(l),isActive=audioLessonQueue.length>0,playLabel=audioLessonComplete?'▶ Play again':audioLessonPaused?'▶ Resume':isActive?'Ⅱ Pause':'▶ Play full lesson';return `${header('Audio lessons','Choose a lesson, press play, and listen to its lesson sentence, vocabulary, examples, and conversation in order. All model clips are bundled for offline listening.','LISTEN & REVIEW')}<section class="card audio-player-card" aria-label="Full lesson audio player"><label for="audioLessonSelect"><b>Choose a lesson</b></label><select id="audioLessonSelect" class="field" aria-label="Choose an audio lesson" onchange="selectAudioLesson(this.value)">${LESSONS.map(x=>`<option value="${x.id}" ${x.id===audioLessonId?'selected':''}>Lesson ${String(x.id).padStart(2,'0')} · ${esc(x.title)}</option>`).join('')}</select><p class="muted">${esc(l.description)} · ${queue.length} audio clips</p><div class="audio-controls"><button id="audioLessonToggle" class="btn" onclick="toggleAudioLesson()">${playLabel}</button>${isActive?`<button class="btn secondary" onclick="restartAudioLesson()">↺ Start over</button>`:''}</div><div class="audio-progress" role="progressbar" aria-label="Audio lesson progress" aria-valuemin="0" aria-valuemax="${queue.length}" aria-valuenow="${isActive?audioLessonIndex:0}"><span id="audioLessonProgress"></span></div><p id="audioLessonStatus" class="notice" role="status"></p>${audioDialogueScene(l)}<div class="audio-current" id="audioLessonCurrent" aria-live="polite"></div></section>`}
function settings(){return `${header('Learning settings & backup','Your data lives in this browser. Export regularly to avoid losing it when clearing site data.','PREFERENCES')}<div class="card"><label class="toggle"><input type="checkbox" ${romaji?'checked':''} onchange="romaji=this.checked;render()"> Show romaji in vocabulary</label><p><label>Interface text size <select class="field" aria-label="Interface text size" onchange="state.fontSize=this.value;applyTextSize();save()"><option value="standard" ${state.fontSize==='standard'?'selected':''}>Standard</option><option value="large" ${state.fontSize==='large'?'selected':''}>Large</option><option value="extra-large" ${state.fontSize==='extra-large'?'selected':''}>Extra large</option></select></label></p><p><label>Daily activity goal <input class="field" type="number" min="1" max="200" value="${state.goal}" onchange="state.goal=Math.max(1,Math.min(200,Number(this.value)||15));save()"></label></p><div class="row"><button class="btn" onclick="exportData()">Export progress JSON</button><label class="btn secondary" for="importFile">Import progress JSON</label><input type="file" id="importFile" accept="application/json,.json" class="hidden" onchange="importData(this.files[0])"></div><p class="notice">Import replaces current progress. Review JSON before importing files from others. Data is not uploaded anywhere.</p><div class="divider"></div><button class="btn secondary" onclick="if(confirm('Delete all local learning progress?')){state=fresh();applyTextSize();save();render()}">Reset progress</button></div>`}
function exportData(){let blob=new Blob([JSON.stringify({version:1,exported:new Date().toISOString(),state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sakura-academy-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importData(file){if(!file)return;try{if(file.size>2000000)throw Error('Backup too large');let d=JSON.parse(await file.text()),s=d.state;if(d.version!==1||!s||typeof s!=='object'||Array.isArray(s)||!Array.isArray(s.answers)||typeof s.xp!=='number')throw Error('Invalid backup structure');for(let k of ['reviews','learned','completed','activity','kana','kanji','handwriting'])if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))throw Error('Invalid '+k);if(s.assessments!==undefined&&(!s.assessments||typeof s.assessments!=='object'||Array.isArray(s.assessments)))throw Error('Invalid assessments');if(s.rewarded!==undefined&&(!s.rewarded||typeof s.rewarded!=='object'||Array.isArray(s.rewarded)))throw Error('Invalid rewarded');if(s.tabVisits!==undefined&&(!s.tabVisits||typeof s.tabVisits!=='object'||Array.isArray(s.tabVisits)))throw Error('Invalid tab visits');if(s.grammarParts!==undefined&&(!s.grammarParts||typeof s.grammarParts!=='object'||Array.isArray(s.grammarParts)))throw Error('Invalid grammar progress');if(s.strictMode!==undefined&&typeof s.strictMode!=='boolean')throw Error('Invalid strictMode');let settingsErrors=validateProgressBackupSettings(s),strictErrors=validateStrictProgressData(s),practiceErrors=validatePracticeProgressData(s);if(settingsErrors.length||strictErrors.length||practiceErrors.length)throw Error([...settingsErrors,...strictErrors,...practiceErrors].join(', '));if(!confirm('Replace all current progress with this backup?'))return;state={...fresh(),...s};state.grammarParts=sanitizeGrammarParts(state.grammarParts,LESSONS);sanitizePracticeProgressData(state);save();render();alert('Backup imported.')}catch(e){alert('Import failed: '+e.message)}}
function render(){let items=[['dashboard','◈','Dashboard','Home'],['n5','五','JLPT N5','N5'],['lessons','▤','Lessons','Learn'],['audio','♫','Audio lessons','Audio'],['kana','あ','Kana studio','Kana'],['handwriting','✎','Write characters','Write'],['kanji','字','Kanji explorer','Kanji'],['flashcards','◇','Flashcards','Cards'],['settings','⚙','Settings','Prefs']];$('sidebar').innerHTML=`<div class="brand"><span class="brandmark">✿</span><span><strong>Sakura Academy</strong><small>日本語を学ぼう</small></span></div><button class="navbtn" onclick="$('sidebar').classList.toggle('collapsed')"><span class="glyph">☰</span><span class="navtext">Collapse menu</span></button>${items.map(x=>`<button class="navbtn ${view===x[0]||(view==='lesson'&&x[0]==='lessons')?'active':''}" aria-label="${x[2]}" onclick="nav('${x[0]}')"><span class="glyph">${x[1]}</span><span class="navtext" data-mobile="${x[3]}">${x[2]}</span></button>`).join('')}`;$('content').innerHTML=({dashboard,lessons:()=>header('Lesson library','Original beginner lessons. Select a lesson to explore its learning modes.')+(strictNotice?`<div class="feedback bad">${esc(strictNotice)}</div>`:'')+(state.strictMode?`<p class="notice">Strict mode is on. Complete Lesson ${strictUnlockedLesson()} to unlock the next lesson.</p>`:'')+lessonCards(),lesson,audio:audioLessons,kana:kanaPage,handwriting,kanji:kanjiPage,n5:n5Page,flashcards,settings})[view]();if(view==='audio')updateAudioLessonStatus();if(view==='handwriting'){setupPracticeCanvas();strokeStep=0;stopStrokeGuide();showStrokeStep(0)}}
function validate(){return validateCourseContent(LESSONS,WORD_GUIDANCE)}
window.addEventListener('error',e=>console.error('App error',e.message));console.info('Content validation:',validate().length?validate():'PASS',LESSONS.length,'lessons',allCards().length,'words',KANA.length,'kana',KANJI.length,'kanji');applyTextSize();render();
